const f = $input.first().json;

const nameParts = (f.lead_name || '').trim().split(' ');
const firstName = nameParts[0] || '';
const lastName = nameParts.slice(1).join(' ') || '';

return [{
  json: {
    firstName,
    lastName,
    fullName: f.lead_name || '',
    email: f.email || '',
    company: f.company || '',
    jobTitle: f.job_title || '',
    practiceType: f.practice_type || '',
    productInterest: f.product_interest || '',
    numVets: f.num_vets || '',
    currentSystem: f.current_system || '',
    painPoint: f.pain_point || '',
    leadSource: f.lead_source || ''
  }
}];

parameters.text:
=Score this inbound veterinary lead and determine routing.

LEAD DATA:
Name: {{ $json.fullName }}
Email: {{ $json.email }}
Practice: {{ $json.company }}
Role: {{ $json.jobTitle }}
Practice Type: {{ $json.practiceType }}
Product Interest: {{ $json.productInterest }}
Number of Vets: {{ $json.numVets }}
Current System: {{ $json.currentSystem }}
Biggest Pain Point: {{ $json.painPoint }}
Source: {{ $json.leadSource }}

=== SCORING CRITERIA ===

HIGH INTENT (score 8-10, route: IMMEDIATE):
- Practice Owner or DVM requesting demo
- Mentions specific pain (slow PACS, offline needs, billing issues)
- Currently using a competitor (IDEXX, Cornerstone, etc.) and unhappy
- Equine practice interested in StableTrack
- Imaging center interested in PACS
- 3+ vets = higher deal size

MEDIUM INTENT (score 5-7, route: NURTURE):
- Vet Tech or Manager (not final decision maker)
- 'Not sure — tell me more' on product
- No specific pain point mentioned
- Came from website (browsing) vs referral (intent)

LOW INTENT (score 1-4, route: DRIP):
- Generic email (gmail, yahoo) with no company
- 'Other' role with no details
- No pain point, no current system mentioned
- Possible student or vendor

=== PRODUCT ROUTING ===
Keystone OMNI: imaging centers, radiology, emergency/specialty, any practice mentioning PACS/DICOM/imaging
StableTrack: equine practices, large animal, mixed practice with equine
Both: mixed practice, or practice mentioning both imaging and equine

Return ONLY valid JSON:
{"score":8,"tier":"Hot","product_fit":"Keystone OMNI","routing":"IMMEDIATE","reasoning":"Practice owner at imaging center, currently on IDEXX, has specific pain","recommended_action":"Schedule demo call within 24 hours","competitor_displacement":"IDEXX — highlight 3x faster transfers and AI quality checks"}

parameters.jsCode:
const lead = $('Prep Form Data').first().json;
const aiRaw = $input.first().json.output || $input.first().json.text || '';

let scoring = {};
try {
  const m = aiRaw.match(/\{[\s\S]*\}/);
  if (m) scoring = JSON.parse(m[0]);
} catch(e) {
  scoring = { score: 5, tier: 'Warm', routing: 'NURTURE', reasoning: aiRaw };
}

const score = scoring.score || 5;
let tier = 'Cold';
if (score >= 8) tier = 'Hot';
else if (score >= 5) tier = 'Warm';

return [{
  json: {
    ...lead,
    aiScore: score,
    tier: scoring.tier || tier,
    productFit: scoring.product_fit || lead.productInterest,
    routing: scoring.routing || 'NURTURE',
    reasoning: scoring.reasoning || '',
    recommendedAction: scoring.recommended_action || '',
    competitorDisplacement: scoring.competitor_displacement || '',
    isHighIntent: score >= 8
  }
}];

